import{_ as e,o as r,c as a,a3 as d}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"常见前端方案索引","description":"","frontmatter":{"title":"常见前端方案索引","outline":[2,3]},"headers":[],"relativePath":"frontend/practices/solutions/index.md","filePath":"frontend/practices/solutions/index.md","lastUpdated":1785666337000}'),o={name:"frontend/practices/solutions/index.md"};function i(n,t,l,s,c,h){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="常见前端方案索引" tabindex="-1">常见前端方案索引 <a class="header-anchor" href="#常见前端方案索引" aria-label="Permalink to &quot;常见前端方案索引&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>方案实践位于单项知识和完整项目之间。每一篇围绕一个可复用的问题场景，组合浏览器能力、框架状态、工程质量、性能、安全和技术决策，给出面向生产约束的可落地方案。</p><p>这里不重复解释基础 API，也不把某个代码片段包装成通用答案。方案必须明确适用条件、数据流、失败路径、验证方法和替代选择；当业务规模、终端环境或安全要求发生变化时，结论也应随之调整。</p><h2 id="高频方案" tabindex="-1">高频方案 <a class="header-anchor" href="#高频方案" aria-label="Permalink to &quot;高频方案&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>核心问题</th><th>主要关联模块</th></tr></thead><tbody><tr><td><a href="/frontend/practices/solutions/large-data-processing">大数据量列表、表格与计算优化</a></td><td>大量数据如何传输、计算、渲染和交互</td><td>性能工程、算法、Worker、虚拟化</td></tr><tr><td><a href="/frontend/practices/solutions/authentication-authorization">登录、会话、鉴权与权限系统</a></td><td>身份如何建立、保持、验证和授权</td><td>Web 应用能力、安全、服务端、状态管理</td></tr><tr><td><a href="/frontend/practices/solutions/mobile-adaptation-compatibility">移动端适配与浏览器兼容方案</a></td><td>如何处理视口、输入、系统栏、软键盘和平台差异</td><td>体验工程、Web API、跨端开发</td></tr><tr><td><a href="/frontend/practices/solutions/large-file-transfer">大文件上传、下载与断点续传</a></td><td>如何分片、校验、重试、恢复并控制资源消耗</td><td>网络、文件 API、服务端与可靠性</td></tr><tr><td><a href="/frontend/practices/solutions/cache-offline-sync">前端缓存、离线与数据同步</a></td><td>本地数据如何缓存、失效、同步和解决冲突</td><td>Storage、Service Worker、缓存一致性</td></tr><tr><td><a href="/frontend/practices/solutions/realtime-reconnection-consistency">实时通信、重连与消息一致性</a></td><td>长连接断开后如何恢复并避免丢失、重复和乱序</td><td>WebSocket、SSE、状态与可靠性</td></tr><tr><td><a href="/frontend/practices/solutions/multi-tab-state-sync">多标签页通信与状态同步</a></td><td>多个页面实例如何选主、通信并保持状态一致</td><td>BroadcastChannel、Storage、Worker</td></tr><tr><td><a href="/frontend/practices/solutions/file-preview-security">文件预览与安全呈现</a></td><td>不可信文件如何分类、限制资源并选择安全渲染器</td><td>Blob、对象 URL、MIME、CSP 与来源隔离</td></tr><tr><td><a href="/frontend/practices/solutions/data-file-export">数据与文件导出</a></td><td>小数据与大任务如何生成、交付并审计稳定文件</td><td>CSV、Blob、异步任务、幂等与权限</td></tr><tr><td><a href="/frontend/practices/solutions/web-print-pagination">Web 打印与分页控制</a></td><td>连续页面如何形成资源稳定、分页可控的打印文档</td><td>打印媒体、分页 CSS、窗口生命周期</td></tr></tbody></table><h2 id="平台与基础设施方案" tabindex="-1">平台与基础设施方案 <a class="header-anchor" href="#平台与基础设施方案" aria-label="Permalink to &quot;平台与基础设施方案&quot;">​</a></h2><p>以下主题已经作为完整项目或技术决策存在，本索引只提供入口，不复制正文：</p><table tabindex="0"><thead><tr><th>主题</th><th>主要入口</th><th>补充决策</th></tr></thead><tbody><tr><td>低代码</td><td><a href="/frontend/practices/schema-low-code">Schema 驱动与低代码平台</a></td><td>从模型、渲染器、扩展协议和平台治理整体实践</td></tr><tr><td>微前端</td><td><a href="/frontend/practices/micro-frontend-platform">微前端平台</a></td><td><a href="/frontend/decisions/architecture/monolith-microfrontend">单体与微前端</a></td></tr><tr><td>Monorepo</td><td><a href="/frontend/practices/engineering-platform">Monorepo 与前端工程平台</a></td><td><a href="/frontend/decisions/architecture/monorepo">多仓库与 Monorepo</a></td></tr><tr><td>组件体系</td><td><a href="/frontend/practices/component-library">组件库与设计系统</a></td><td><a href="/frontend/decisions/ui/component-library">自研或引入组件库</a></td></tr><tr><td>前端监控</td><td><a href="/frontend/practices/observability-sdk">前端监控 SDK</a></td><td><a href="/frontend/decisions/quality/observability">自研或采购监控能力</a></td></tr></tbody></table><h2 id="方案写作结构" tabindex="-1">方案写作结构 <a class="header-anchor" href="#方案写作结构" aria-label="Permalink to &quot;方案写作结构&quot;">​</a></h2><p>本组方案正文统一按照以下结构展开：</p><ol><li>定义问题、规模、运行环境和不处理的边界。</li><li>拆解功能路径、数据流、异常路径和质量要求。</li><li>比较候选方案，说明选择条件和放弃项。</li><li>给出关键数据结构、接口、状态机或时序设计。</li><li>实现决定方案性质的核心部分，而不是堆砌样板代码。</li><li>处理安全、性能、兼容性、降级和恢复。</li><li>使用测试、性能数据和故障实验验证结论。</li><li>记录容量上限、演进条件和需要重新决策的触发点。</li></ol><h2 id="与其他模块的边界" tabindex="-1">与其他模块的边界 <a class="header-anchor" href="#与其他模块的边界" aria-label="Permalink to &quot;与其他模块的边界&quot;">​</a></h2><ul><li><a href="/frontend/guide/core/">核心知识</a>解释方案依赖的语言、Web API 和框架能力。</li><li><a href="/frontend/guide/engineering/">工程体系</a>提供质量、性能、安全和生产运行保障。</li><li><a href="/frontend/topics/">专题进阶</a>深入算法、图形、跨端和 AI 等专项技术。</li><li><a href="/frontend/decisions/">技术决策</a>比较候选方向，本模块继续完成方案设计与验证。</li><li>项目实战中的其他分组把多个方案组合成完整业务、基础设施或平台。</li></ul>',14)])])}const u=e(o,[["render",i]]);export{p as __pageData,u as default};
